written = 0
for cid in IDS:
    d = P[cid]
    obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    written += 1

# self-verification: re-open each file by exact id, parse, check fields and trigger shape
ok = 0
counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        o = json.load(f)
    assert o["case_id"] == cid
    assert set(o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    assert isinstance(o["confidence"], float) and 0.0 <= o["confidence"] <= 1.0
    t = o["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    assert isinstance(t["reason"], str)
    if cid.startswith("BQ-0") and cid != "BQ-001":
        for k in counts:
            counts[k] += 1 if t[k] else 0
    else:
        assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    ok += 1
print("written:", written, "verified:", ok)
print("liuyao trigger counts (BQ-010..BQ-016, 7 cases):", counts)
